"""pandas-ta stub — indicators implemented directly using pandas/numpy"""
version = "0.3.14b0-stub"

def ema(close, length=None, **kwargs):
    return close.ewm(span=length, adjust=False).mean()

def sma(close, length=None, **kwargs):
    return close.rolling(window=length).mean()

def rsi(close, length=14, **kwargs):
    delta = close.diff()
    gain = delta.clip(lower=0).rolling(length).mean()
    loss = (-delta.clip(upper=0)).rolling(length).mean()
    rs = gain / loss
    return 100 - (100 / (1 + rs))

def atr(high, low, close, length=14, **kwargs):
    prev_close = close.shift(1)
    tr = (high - low).combine((prev_close - high).abs(), max).combine((prev_close - low).abs(), max)
    return tr.rolling(length).mean()

def stoch(high, low, close, k=14, d=3, **kwargs):
    lowest_low = low.rolling(k).min()
    highest_high = high.rolling(k).max()
    stoch_k = 100 * (close - lowest_low) / (highest_high - lowest_low)
    stoch_d = stoch_k.rolling(d).mean()
    import pandas as pd
    return pd.DataFrame({"STOCHk": stoch_k, "STOCHd": stoch_d})

def macd(close, fast=12, slow=26, signal=9, **kwargs):
    ema_fast = close.ewm(span=fast, adjust=False).mean()
    ema_slow = close.ewm(span=slow, adjust=False).mean()
    macd_line = ema_fast - ema_slow
    signal_line = macd_line.ewm(span=signal, adjust=False).mean()
    histogram = macd_line - signal_line
    import pandas as pd
    return pd.DataFrame({"MACD": macd_line, "MACDs": signal_line, "MACDh": histogram})
